using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class MaterialMarketTests
{
    static readonly EntityId Site=new("site:castle");
    internal static WorldSession Start(string person="person:nobunaga",ulong seed=1)=>new(NewGameWorld.Create(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],person,seed,historicalCatalog:HistoricalStartCatalog.Current,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:MaterialMarkets.Policy));
    static EntityId Here(WorldSession s)=>s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==s.PlayerControl).Site!.Value;
    static CommandResult Act(WorldSession s,TradeAction a,EntityId? contract=null,long n=0,string? kind=null,EntityId? to=null,string? id=null)=>s.TradeRice(new(new(id??"request:materials/"+s.Revision),a,Here(s),contract,to,n){Commodity=kind},s.PlayerControl,s.Revision);
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
    static EntityId Buy(WorldSession s,string? kind,long n,EntityId? to=null){Good(Act(s,TradeAction.Quote,n:n,kind:kind,to:to??Here(s)));var id=s.DiagnosticSnapshot().Trade!.Deals.Last().Id;Good(Act(s,TradeAction.Accept,id));Good(Act(s,TradeAction.Collect,id));return id;}
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long before=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>before);}}
    static long Day(int y,int m,int d)=>(new DateOnly(y,m,d).DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;
    static TradeMarket Market(WorldSession s)=>s.DiagnosticSnapshot().Trade!.Markets.Single(m=>m.Site==Here(s));
    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:materials-travel/"+s.Revision,node),s.Revision));Advance(s,s.Seconds+2);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt+1);}
    static EntityId Work(WorldSession s){Good(s.ConsultVillage(new(new("request:water-talk/"+s.Revision),VillageAction.ProposeWater,Here(s),Amount:200),s.PlayerControl,s.Revision));var q=s.DiagnosticSnapshot().Villages!.Proposals.Last().Id;Good(s.ConsultVillage(new(new("request:water-agree/"+s.Revision),VillageAction.Confirm,Here(s),q),s.PlayerControl,s.Revision));return q;}
    static CommandResult Begin(WorldSession s,EntityId q)=>s.ConsultVillage(new(new("request:water-start/"+s.Revision),VillageAction.Deliver,Here(s),q,200),s.PlayerControl,s.Revision);
    [Fact]public void ThirtyNationalHubsHaveSeparateMerchantAndFacilityIdentities(){var s=Start();var w=s.DiagnosticSnapshot();Assert.Equal(30,w.Materials!.Profiles.Length);Assert.Equal(30,w.Trade!.Markets.Length);Assert.All(w.Materials.Profiles,p=>{Assert.NotEqual(p.Site,p.Merchant);Assert.NotEqual(p.Site,p.Facility);Assert.Contains(w.Definitions.Sites,x=>x.Id==p.Site);Assert.Contains("trial",p.Basis);});Assert.All(w.Materials.Profiles.Where(p=>p.Residents!=null),p=>Assert.Contains(w.Villages!.Organizations,o=>o.Id==p.Residents));Assert.Equal(3,w.Materials.Profiles.Count(p=>p.Residents!=null));Assert.Equal(20,MaterialMarkets.LocalHouse(w)!.Wood);Assert.True(s.VillageView()!.CanPromise);}
    [Theory][InlineData(null,100)][InlineData("wood",100)][InlineData("weapons",20)]public void AllGoodsUseActualSharedMoneyAndWeight(string? kind,long n){var s=Start();var m=Market(s);long price=kind==null?s.RegionalTradeView()!.BuyPrice:s.RegionalTradeView()!.Goods!.Single(g=>g.Kind==kind).BuyPrice;var d=Buy(s,kind,n);Assert.Equal(100,n*MaterialMarkets.MassKg(kind));Assert.Equal(1000-price*n,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(MaterialMarkets.Stock(m,kind)-n,MaterialMarkets.Stock(Market(s),kind));Assert.Equal(kind,s.DiagnosticSnapshot().Trade!.Deals.Single().Commodity);}
    [Theory][InlineData("wood",101)][InlineData("weapons",21)][InlineData("unknown",1)]public void InvalidCommodityOrOverweightIsAtomic(string kind,long n){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Quote,n:n,kind:kind,to:new("site:kofu")).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void OneCarryingContractPreventsCrossProductCapacityBypass(){var s=Start();Buy(s,"wood",100);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Quote,n:20,kind:"weapons",to:new("site:kofu")).Code);}
    [Fact]public void SameSitePurchaseCanEnterHouseButCannotRefundPrivateMoney(){var s=Start();var id=Buy(s,"wood",10);long wallet=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);Good(Act(s,TradeAction.SupplyHouse,id));Assert.Equal(30,MaterialMarkets.LocalHouse(s.DiagnosticSnapshot())!.Wood);Assert.Equal(wallet,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(3000,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.SupplyHouse,id).Code);}
    [Fact]public void WeaponInventoryDoesNotCreateSoldiersOrCommand(){var s=Start();var w=s.DiagnosticSnapshot();var d=Buy(s,"weapons",2);Good(Act(s,TradeAction.SupplyHouse,d));Assert.Equal(12,MaterialMarkets.LocalHouse(s.DiagnosticSnapshot())!.Weapons);Assert.Equal(ContractJson.Write(w.Units),ContractJson.Write(s.DiagnosticSnapshot().Units));Assert.Equal(ContractJson.Write(w.Offices),ContractJson.Write(s.DiagnosticSnapshot().Offices));Assert.Empty(s.DiagnosticSnapshot().Transfers);}
    [Fact]public void WorkConsumesTenWoodAndShortageCannotSpendRiceOrLabor(){var s=Start();for(int i=0;i<2;i++){var q=Work(s);Good(Begin(s,q));Advance(s,s.Seconds+7*86400);}Assert.Equal(0,MaterialMarkets.LocalHouse(s.DiagnosticSnapshot())!.Wood);Assert.Equal(20,MaterialMarkets.LocalHouse(s.DiagnosticSnapshot())!.WoodUsed);var third=Work(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Begin(s,third).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));var d=Buy(s,"wood",10);Good(Act(s,TradeAction.SupplyHouse,d));Good(Begin(s,third));Assert.Equal(0,MaterialMarkets.LocalHouse(s.DiagnosticSnapshot())!.Wood);Advance(s,s.Seconds+7*86400);Assert.Equal(130,s.CommunityEconomyView()!.Accounts.Water);}
    [Fact]public void MonthlyProductionPaysWorkersUsesFiniteInputsAndBuysWithinTheirWallet(){var s=Start();Advance(s,Day(1560,2,1));var months=s.DiagnosticSnapshot().Materials!.Months;Assert.Equal(3,months.Length);Assert.All(months,p=>{Assert.Equal(20,p.WoodMade);Assert.Equal(2,p.WeaponsMade);Assert.Equal(20,p.Wages);Assert.Equal(2,p.WoodBought);Assert.Equal(1,p.WeaponsBought);Assert.InRange(MaterialMarkets.WorkerCash+p.Wages-p.Income,0,MaterialMarkets.WorkerCash+p.Wages);});Assert.Equal(218,MaterialMarkets.Stock(Market(s),"wood"));Assert.Equal(41,MaterialMarkets.Stock(Market(s),"weapons"));Assert.Equal(4013,Market(s).Cash);}
    [Fact]public void DynamicWorkshopsRemainThreeKnownCommunitiesNotInventedNationalPopulation(){var s=Start();Advance(s,Day(1560,2,1));Assert.All(s.DiagnosticSnapshot().Materials!.Months,p=>Assert.Contains(p.Site,CommunityEconomy.Sites));Assert.Equal(200,MaterialMarkets.Stock(s.DiagnosticSnapshot().Trade!.Markets.Single(m=>m.Site.Value=="site:kyoto"),"wood"));}
    [Fact]public void MonthlyCashConservationIncludesResidentWalletAndTradeNet(){var s=Start();var d=Buy(s,"wood",10);Good(Act(s,TradeAction.Cancel,d));Good(Act(s,TradeAction.OfferSale,d));Good(Act(s,TradeAction.Deliver,d));Advance(s,Day(1560,2,1));var w=s.DiagnosticSnapshot();long wages=w.Materials!.Months.Sum(p=>p.Wages-p.Income);Assert.Equal(RegionalTrade.InitialCash*w.Trade!.Markets.Length,w.Trade.Markets.Sum(m=>m.Cash)+RegionalTrade.Net(w,NewGameWork.Wallet(s.PlayerControl))+wages);Assert.All(w.Trade.Deals.Where(d=>d.Phase==TradePhase.Delivered),d=>Assert.True(w.Trade.Markets.Single(m=>m.Site==d.SaleSite).Cash>=d.Amount*d.SalePrice));Good(Act(s,TradeAction.Settle,d));}
    [Fact]public void NationwideTransportAndSettlementUseSamePhysicalRoute(){var s=Start();var d=Buy(s,"wood",2,new("site:kyoto"));Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:remote-sell"),TradeAction.OfferSale,new("site:kyoto"),d),s.PlayerControl,s.Revision).Code);Move(s,"kyoto");Good(Act(s,TradeAction.OfferSale,d));Good(Act(s,TradeAction.Deliver,d));long before=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);long price=s.DiagnosticSnapshot().Trade!.Deals.Single().SalePrice;Good(Act(s,TradeAction.Settle,d));Assert.Equal(before+price*2,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Settle,d).Code);}
    [Fact]public void LocalViewDoesNotPublishOtherMarketsCurrentStock(){var s=Start();Advance(s,Day(1560,2,1));var text=System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.RegionalTradeView()));Assert.DoesNotContain("site:kofu",text);Assert.DoesNotContain("site:kyoto",text);Assert.DoesNotContain("WorkersCash",text);Assert.Equal(2,s.RegionalTradeView()!.Goods!.Length);}
    [Fact]public void NpcWaterWorkWaitsAtActualMaterialShortage(){var s=Start();Advance(s,Day(1560,5,1));var w=s.DiagnosticSnapshot();Assert.Equal(120,w.Communities!.Accounts.Single(a=>a.Site.Value=="site:kofu").Water);Assert.Equal(0,w.Materials!.Houses.Single(h=>h.Site.Value=="site:kofu").Wood);Assert.Contains(w.CommunityAdministration!.Decisions,d=>d.Site.Value=="site:kofu"&&d.Reason.Contains("木材"));}
    [Fact]public void AcceptedStockAndPlayerMoneyRemainReservedAcrossNpcProduction(){var s=Start();Advance(s,Day(1560,2,1)-10);Good(Act(s,TradeAction.Quote,n:100,kind:"wood",to:new("site:kofu")));var d=s.DiagnosticSnapshot().Trade!.Deals.Single().Id;Good(Act(s,TradeAction.Accept,d));long reserved=1000-NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);Advance(s,Day(1560,2,1));Assert.Equal(reserved,1000-NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.True(s.RegionalTradeView()!.Goods!.Single(g=>g.Kind=="wood").Available>=0);Good(Act(s,TradeAction.Collect,d));Assert.Equal(100,s.DiagnosticSnapshot().Trade!.Deals.Single().Amount);}
    [Fact]public void QuoteExpiryReleasesAllProductReservationWithoutMintingGoods(){var s=Start();Good(Act(s,TradeAction.Quote,n:20,kind:"weapons",to:new("site:kofu")));var id=s.DiagnosticSnapshot().Trade!.Deals.Single().Id;Good(Act(s,TradeAction.Accept,id));Assert.Equal(500,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Advance(s,7*86400+1);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(40,MaterialMarkets.Stock(Market(s),"weapons"));Assert.Equal(TradePhase.Expired,s.DiagnosticSnapshot().Trade!.Deals.Single().Phase);}
    [Fact]public void RepeatedAndConflictingCommodityCommandsCannotDuplicateStock(){var s=Start();Good(Act(s,TradeAction.Quote,n:10,kind:"wood",to:Site,id:"request:quote"));Assert.Equal(ResultCode.AlreadyAccepted,Act(s,TradeAction.Quote,n:10,kind:"wood",to:Site,id:"request:quote").Code);Assert.Equal(ResultCode.IdPayloadConflict,Act(s,TradeAction.Quote,n:10,kind:"weapons",to:Site,id:"request:quote").Code);Assert.Single(s.DiagnosticSnapshot().Trade!.Deals);}
    [Fact]public void ForgedProductionOrProfilesCannotLoad(){var s=Start();Advance(s,Day(1560,2,1));var w=s.DiagnosticSnapshot();w.Materials=w.Materials! with{Months=[..w.Materials.Months.Select(p=>p with{WoodMade=999})]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Materials=w.Materials! with{Profiles=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Materials=w.Materials! with{Months=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OldV7BytesAndLegacyRiceContractsArePreserved(){var s=CommunityStewardshipTests.Start();var b=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("Materials",System.Text.Encoding.UTF8.GetString(b));Assert.DoesNotContain("Goods",System.Text.Encoding.UTF8.GetString(b));Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:old-goods"),TradeAction.Quote,new("site:kofu"),Destination:Site,Amount:1){Commodity="wood"},s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();w.Materials=Start().DiagnosticSnapshot().Materials;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]public void ActualGenerationRecoveryPreservesProductionTravelDebtAndHouseUse(int phase){var a=Start();EntityId? deal=null;if(phase is 0 or 4)Advance(a,Day(1560,2,1));if(phase is 1 or 2 or 3){deal=Buy(a,"wood",10,new("site:kyoto"));if(phase==1){Good(a.Submit(TravelWorld.Move(a.DiagnosticSnapshot(),"request:save-goods-trip","kyoto"),a.Revision));Advance(a,a.Seconds+2);}if(phase==2){Good(Act(a,TradeAction.OfferSale,deal));Good(Act(a,TradeAction.Deliver,deal));}if(phase==3)Good(Act(a,TradeAction.SupplyHouse,deal));}if(phase==4){var q=Work(a);Good(Begin(a,q));}a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"materials-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"goods",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("goods"),host.Current,host.Current.Revision));var b=host.Current;Assert.Equal(ContractJson.Write(a.RegionalTradeView()),ContractJson.Write(b.RegionalTradeView()));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"materials-"+phase+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,"materials-"+phase+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}foreach(var s in new[]{a,b}){if(phase==2)Good(Act(s,TradeAction.Settle,deal));Advance(s,s.Seconds+40*86400);}Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void FirstMonthDoesNotDependOnAdvanceChunkSize(){var a=Start();var b=Start();Advance(a,Day(1560,3,1));Advance(b,Day(1560,2,1));Advance(b,Day(1560,3,1));Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Materials),ContractJson.Write(b.DiagnosticSnapshot().Materials));Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot().Trade),ContractJson.Write(b.DiagnosticSnapshot().Trade));}
    [Fact]public void NormalProfileConnectsGoodsWithStewardshipAndNationalTravel(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"materials-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",1,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,MaterialMarkets.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);var s=new WorldSession(NewCampaignStore.Build(store.Read(p.Instance)));Assert.NotNull(s.StewardshipView());Assert.NotNull(s.RegionalTradeView()!.Goods);Assert.Equal(30,s.DiagnosticSnapshot().Trade!.Markets.Length);}

    [Fact]public void ActualHungerStopsNonEssentialProductionAndResidentPurchases(){var s=Start(seed:285);Advance(s,Day(1560,10,1));Good(s.ManageCommunity(new(new("request:materials-levy"),Site,EconomyAction.CollectLevy,3000),s.PlayerControl,s.Revision));Advance(s,Day(1561,7,1));Assert.Equal(1000,s.CommunityEconomyView()!.Accounts.Hunger);var p=s.DiagnosticSnapshot().Materials!.Months.Last(m=>m.Site==Site);Assert.Equal(0,p.WoodMade+p.WeaponsMade+p.Wages+p.WoodBought+p.WeaponsBought+p.Income);}
    [Fact]public void SalaryRiceAndMaterialMarketsShareActualMoneyWithoutMixingInventories(){var worker=HistoricalHouseholdCatalog.Edition.People.Single().Id;var s=Start(worker.Value);var head=new EntityId("person:shingen");var site=Here(s);Good(s.ManageSalary(new(new("request:materials-wage"),SalaryAction.Propose,head,site,Amount:20),worker,s.Revision));var q=s.DiagnosticSnapshot().Salary!.Quotes.Single().Id;Good(s.ManageSalary(new(new("request:materials-wage-confirm"),SalaryAction.Confirm,head,site,q),worker,s.Revision));Advance(s,Day(1560,2,1));Good(s.ManageSalary(new(new("request:materials-wage-prepare"),SalaryAction.Prepare,head,site,q,20),worker,s.Revision));Good(s.ManageSalary(new(new("request:materials-wage-receive"),SalaryAction.Receive,head,site,q,Preparation:new("request:materials-wage-prepare")),worker,s.Revision));Good(Act(s,TradeAction.OfferOwnRice,to:site,n:20));var d=s.DiagnosticSnapshot().Trade!.Deals.Single().Id;Good(Act(s,TradeAction.OfferSale,d));Good(Act(s,TradeAction.Deliver,d));Good(Act(s,TradeAction.Settle,d));Assert.Equal(0,HouseSalary.PrivateRice(s.DiagnosticSnapshot(),worker));Assert.Equal(1060,NewGameWork.Balance(s.DiagnosticSnapshot(),worker));Assert.Equal(218,MaterialMarkets.Stock(Market(s),"wood"));}
    [Fact]public void DelegatedWaterAlsoConsumesActualHouseMaterialWithoutUsingPrivateWealth(){var worker=HistoricalHouseholdCatalog.Edition.People.Single().Id;var s=Start(worker.Value);var site=Here(s);Good(s.ManageStewardship(new(new("request:material-steward"),StewardAction.Assign,site,new("person:shingen"),ReturnAddress:site),worker,s.Revision));var g=s.DiagnosticSnapshot().Stewardship!.Grants.Single().Id;Good(s.ManageStewardship(new(new("request:material-delegated-work"),StewardAction.Operate,site,Grant:g,Operation:EconomyAction.ImproveWater,Amount:200),worker,s.Revision));Assert.Equal(10,s.DiagnosticSnapshot().Materials!.Houses.Single(h=>h.Site==site).Wood);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),worker));}
}
